import{_ as u,a0 as l,w as p,s,ao as r,I as a,x as i,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Authenticator：一個 Linux 上的 Authy 的簡單的開源替代品 | LCTT x X-CMD","titleTemplate":false,"description":"Authenticator：一個 Linux 上的 Authy 的簡單的開源替代品 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Authenticator：一個 Linux 上的 Authy 的簡單的開源替代品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Authenticator：一個 Linux 上的 Authy 的簡單的開源替代品 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221117.1 ⭐️ Authenticator A Simple Open-Source App to Replace Authy on Linux","title":"Authenticator：一個 Linux 上的 Authy 的簡單的開源替代品","tag":"202212","desc":""},"relativePath":"202212/20221117.1 ⭐️ Authenticator A Simple Open-Source App to Replace Authy on Linux.md","filePath":"[post].md"}'),h={name:"202212/20221117.1 ⭐️ Authenticator A Simple Open-Source App to Replace Authy on Linux.md"};function d(m,t,A,f,x,g){const e=l("Link");return p(),s("div",null,[t[21]||(t[21]=r('<h1 id="authenticator-一個-linux-上的-authy-的簡單的開源替代品" tabindex="-1">Authenticator：一個 Linux 上的 Authy 的簡單的開源替代品 <a class="header-anchor" href="#authenticator-一個-linux-上的-authy-的簡單的開源替代品" aria-label="Permalink to “Authenticator：一個 Linux 上的 Authy 的簡單的開源替代品”">​</a></h1><p>Authy 是一款流行的應用，用於存儲和管理雙因素代碼。它是一項基於雲的服務，可為你提供便利的工業級安全性。不幸的是，它不是開源的。</p><p>你會考慮在 Linux 桌面上使用更直接（和開源）的身份驗證器應用嗎？</p><p>嗯，當然，你不能使用雲同步。但是你可以為雙因素身份驗證碼做個備份。記住這點，讓我告訴你更多有關 Authenticator 的信息。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/11/authenticator-app-ft.png" alt="authenticator app ft"></p><h3 id="authenticator-生成雙因素身份驗證代碼" tabindex="-1">Authenticator：生成雙因素身份驗證代碼 <a class="header-anchor" href="#authenticator-生成雙因素身份驗證代碼" aria-label="Permalink to “Authenticator：生成雙因素身份驗證代碼”">​</a></h3><p>當你啓用在線服務的雙因素身份驗證時，大多數服務都會為你提供令牌/QR 碼，你可以添加/掃描以生成代碼。</p><p>Authenticator 就是這樣一款適用於 Linux 的應用，他可讓你添加雙因素身份驗證碼。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/11/authenticator-ui.png" alt="authenticator ui"></p><p>它是一個自由開源的應用，具有添加各種支持雙因素身份驗證的令牌和網站的基本功能。</p><h3 id="身份驗證器的特點" tabindex="-1">身份驗證器的特點 <a class="header-anchor" href="#身份驗證器的特點" aria-label="Permalink to “身份驗證器的特點”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/11/authenticator-auto-lock.png" alt="authenticator 自動鎖定"></p><p>你獲得的一些基本功能包括：</p><ul><li>使用相機或截圖的二維碼掃描器</li><li>使用密碼保護應用</li><li>自動鎖定應用</li><li>支持各種算法（SHA-1/SHA-256/SHA-512）</li><li>支持基於時間/基於計數器/流式計算方法</li><li>備份/恢復選項（FreeOTP、Aegis 和 OTP、Bitwarden 和 Google Authenticator）</li></ul><p>你可以設置自定義選項，並能夠根據服務提供的支持添加自定義的提供者。可以為提供者添加自定義圖標，以幫助你區分身份驗證代碼。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/11/authenticator-custom-provider.png" alt="authenticator 自定義提供程序"></p><p>在大多數情況下，默認設置應該適用於網站。但是，如果它不起作用，你可能需要與提供者核實確切的詳細信息。</p><p>該應用還具有開箱即用的多個提供者，例如 Google Drive 和 Proton Mail。因此，你無需為添加的每個條目添加自定義配置。</p><h3 id="在-linux-上安裝-authenticator" tabindex="-1">在 Linux 上安裝 Authenticator <a class="header-anchor" href="#在-linux-上安裝-authenticator" aria-label="Permalink to “在 Linux 上安裝 Authenticator”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/11/authenticator-add-new-code.png" alt="authenticator 添加新代碼"></p><p>Authenticator 以 Flatpak 的形式提供。因此，你可以將它安裝在任何 Linux 發行版上。</p><p>只需輸入以下命令即可安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install flathub com.belmoussaoui.Authenticator</span></span></code></pre></div>',23)),a("p",null,[t[1]||(t[1]=i("你可以前往其 ",-1)),n(e,{href:"https://flathub.org/apps/details/com.belmoussaoui.Authenticator"},{default:o(()=>[...t[0]||(t[0]=[i("Flathub",-1)])]),_:1}),t[2]||(t[2]=i(" 或 GitLab 頁面探索更多信息。",-1))]),a("p",null,[t[4]||(t[4]=i("如果你是 Linux 世界的新手，請參閲我們的 ",-1)),n(e,{href:"https://itsfoss.com/flatpak-guide/"},{default:o(()=>[...t[3]||(t[3]=[i("Flatpak 指南",-1)])]),_:1}),t[5]||(t[5]=i(" 進行設置。你的軟件中心可能已經啓用了 Flatpak 集成。這種情況下，你可以搜索安裝它。",-1))]),t[22]||(t[22]=a("h3",{id:"使用開源身份驗證器應用確保安全性和可靠性",tabindex:"-1"},[i("使用開源身份驗證器應用確保安全性和可靠性 "),a("a",{class:"header-anchor",href:"#使用開源身份驗證器應用確保安全性和可靠性","aria-label":"Permalink to “使用開源身份驗證器應用確保安全性和可靠性”"},"​")],-1)),t[23]||(t[23]=a("p",null,"我們經常依賴雲驅動的工具來處理所有事情。當然，這很方便。",-1)),t[24]||(t[24]=a("p",null,"但是，有時桌面應用更有用。如果你也這麼想並考慮進行轉換，Authenticator 可能是一款值得安裝的出色的應用，可以用於雙因素身份驗證碼。",-1)),t[25]||(t[25]=a("hr",null,null,-1)),a("p",null,[t[7]||(t[7]=i("via: ",-1)),n(e,{href:"https://itsfoss.com/authenticator/"},{default:o(()=>[...t[6]||(t[6]=[i("https://itsfoss.com/authenticator/",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=i("作者：",-1)),n(e,{href:"https://itsfoss.com/author/ankush/"},{default:o(()=>[...t[8]||(t[8]=[i("Ankush Das",-1)])]),_:1}),t[13]||(t[13]=i(" 選題：",-1)),n(e,{href:"https://github.com/lkxed"},{default:o(()=>[...t[9]||(t[9]=[i("lkxed",-1)])]),_:1}),t[14]||(t[14]=i(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:o(()=>[...t[10]||(t[10]=[i("geekpi",-1)])]),_:1}),t[15]||(t[15]=i(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[11]||(t[11]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[18]||(t[18]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[16]||(t[16]=[i("LCTT",-1)])]),_:1}),t[19]||(t[19]=i(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...t[17]||(t[17]=[i("Linux中國",-1)])]),_:1}),t[20]||(t[20]=i(" 榮譽推出",-1))])])}const T=u(h,[["render",d]]);export{b as __pageData,T as default};
